args<-commandArgs(TRUE);P<-normalizePath(args[1]);W<-file.path(P,'work/2026-11-06-populus-compartment-rings');S<-file.path(P,'biofigure');library(ggplot2);library(grid);d<-readRDS(file.path(W,'prepared-data.rds'));cols<-c(A='#26B3A3',B='#F49B70');radii<-data.frame(pangene_class=c('Core','Dispensable','Private'),inner=c(0,13,26),outer=c(9,20,33),class_y=c(-11,-23,-36),label_r=c(5,16.5,29.5));d<-merge(d,radii,by='pangene_class',sort=FALSE);d<-d[order(d$ring_order,d$compartment),];d$start<-ave(d$proportion,d$pangene_class,FUN=function(x)c(0,head(cumsum(x),-1)))*2*pi;d$end<-d$start+d$proportion*2*pi
